INSERT INTO public.tags (slug, name, name_vi, category, definition_en, definition_vi, aliases, kind)
SELECT slug, name, name_vi, category, definition_en, definition_vi,
  CASE WHEN aliases = '' THEN '{}'::text[] ELSE string_to_array(aliases, '|') END, kind::public.tag_kind FROM catalog
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_vi = EXCLUDED.name_vi,
  category = EXCLUDED.category, definition_en = EXCLUDED.definition_en,
  definition_vi = EXCLUDED.definition_vi, aliases = EXCLUDED.aliases, kind = EXCLUDED.kind;
COMMIT;
